/**
 * Runtime native-decode support probe (ARCHITECTURE §5.2). Uses a tiny
 * committed AVIF (generated by scripts/generate-fixtures.mjs with the real
 * codec) — results are cached for the session. Runs in main threads and
 * workers; absent in Node (callers guard on `createImageBitmap`).
 */
import { TINY_AVIF_BASE64 } from "./avif-probe";

export interface NativeDecodeSupport {
  avif: boolean;
}

let cached: NativeDecodeSupport | null = null;

function base64ToBlob(base64: string, mime: string): Blob {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return new Blob([bytes], { type: mime });
}

export async function getNativeDecodeSupport(): Promise<NativeDecodeSupport> {
  if (cached) return cached;
  let avif = false;
  try {
    const bitmap = await createImageBitmap(base64ToBlob(TINY_AVIF_BASE64, "image/avif"));
    avif = bitmap.width > 0;
    bitmap.close();
  } catch {
    avif = false;
  }
  cached = { avif };
  return cached;
}
